            self.filter.filter(request)

    def test_filter_invalid_path_value(self):
        request = {'path': 123, 'method': 'POST'}
        with self.assertRaises(TypeError):
            self.filter.filter(request)

    def test_filter_invalid_method_value(self):
        request = {'path': '/login', 'method': 123}
        with self.assertRaises(TypeError):
            self.filter.filter(request)

    def test_filter_valid_request(self):
        request = {'path': '/login', 'method': 'POST'}
        self.assertTrue(self.filter.filter(request))
